namespace sv_a31f5e309d904be8aedf51eca8a097d4.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="_screenSize" Name="ScreenSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    private ScreenSize _screenSize = ScreenSize.Desktop;
    private IJSObjectReference? _module;
    private DotNetObjectReference<ScreenSizeProvider>? _selfRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _selfRef = DotNetObjectReference.Create(this);
        _module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./_content/sv-a31f5e309d904be8aedf51eca8a097d4/screenSize.js");
        await _module.InvokeVoidAsync("observe", _selfRef);
    }

    [JSInvokable]
    public Task OnWidthChanged(int width)
    {
        var next = width switch
        {
            < 768 => ScreenSize.Mobile,
            < 1024 => ScreenSize.Tablet,
            _ => ScreenSize.Desktop
        };

        if (next != _screenSize)
        {
            _screenSize = next;
            StateHasChanged();
        }

        return Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("dispose");
            await _module.DisposeAsync();
        }
        _selfRef?.Dispose();
    }
}

let handler = null;

export function observe(dotNetRef) {
    dispose();
    handler = () => dotNetRef.invokeMethodAsync("OnWidthChanged", window.innerWidth);
    window.addEventListener("resize", handler);
    handler(); // send initial width immediately
}

export function dispose() {
    if (handler) {
        window.removeEventListener("resize", handler);
        handler = null;
    }
}

